from itertools import product

# Q8 elements as strings
elements = ['1', '-1', 'i', '-i', 'j', '-j', 'k', '-k']

# Build multiplication table from the given table
# Parse the multiplication table
table = {
    ('1','1'):'1', ('1','-1'):'-1', ('1','i'):'i', ('1','-i'):'-i', ('1','j'):'j', ('1','-j'):'-j', ('1','k'):'k', ('1','-k'):'-k',
    ('-1','1'):'-1', ('-1','-1'):'1', ('-1','i'):'-i', ('-1','-i'):'i', ('-1','j'):'-j', ('-1','-j'):'j', ('-1','k'):'-k', ('-1','-k'):'k',
    ('i','1'):'i', ('i','-1'):'-i', ('i','i'):'-1', ('i','-i'):'1', ('i','j'):'k', ('i','-j'):'-k', ('i','k'):'-j', ('i','-k'):'j',
    ('-i','1'):'-i', ('-i','-1'):'i', ('-i','i'):'1', ('-i','-i'):'-1', ('-i','j'):'-k', ('-i','-j'):'k', ('-i','k'):'j', ('-i','-k'):'-j',
    ('j','1'):'j', ('j','-1'):'-j', ('j','i'):'-k', ('j','-i'):'k', ('j','j'):'-1', ('j','-j'):'1', ('j','k'):'i', ('j','-k'):'-i',
    ('-j','1'):'-j', ('-j','-1'):'j', ('-j','i'):'k', ('-j','-i'):'-k', ('-j','j'):'1', ('-j','-j'):'-1', ('-j','k'):'-i', ('-j','-k'):'i',
    ('k','1'):'k', ('k','-1'):'-k', ('k','i'):'j', ('k','-i'):'-j', ('k','j'):'-i', ('k','-j'):'i', ('k','k'):'-1', ('k','-k'):'1',
    ('-k','1'):'-k', ('-k','-1'):'k', ('-k','i'):'-j', ('-k','-i'):'j', ('-k','j'):'i', ('-k','-j'):'-i', ('-k','k'):'1', ('-k','-k'):'-1',
}

def mult(a, b):
    return table[(a, b)]

def inverse(a):
    for b in elements:
        if mult(a, b) == '1':
            return b
    return None

# Verify inverses
print("Inverses:")
for a in elements:
    print(f"  {a}^-1 = {inverse(a)}")

# Find all subgroups
def is_subgroup(S):
    if '1' not in S:
        return False
    for a in S:
        if inverse(a) not in S:
            return False
        for b in S:
            if mult(a, b) not in S:
                return False
    return True

# Generate all subsets and check
from itertools import combinations
subgroups = []
for r in range(1, 9):
    for subset in combinations(elements, r):
        S = set(subset)
        if is_subgroup(S):
            subgroups.append(frozenset(S))

print(f"\nAll subgroups ({len(subgroups)}):")
for sg in sorted(subgroups, key=lambda s: (len(s), sorted(s))):
    print(f"  {sorted(sg)}")

# Check normality: H is normal if gHg^{-1} = H for all g
def is_normal(H):
    Hset = set(H)
    for g in elements:
        conj = {mult(mult(g, h), inverse(g)) for h in H}
        if conj != Hset:
            return False
    return True

print("\nNormality check:")
for sg in sorted(subgroups, key=lambda s: (len(s), sorted(s))):
    normal = is_normal(set(sg))
    print(f"  {sorted(sg)} -> {'NORMAL' if normal else 'NOT normal'}")

# Also compute commutator subgroup G' = [G,G]
commutators = set()
for a in elements:
    for b in elements:
        # [a,b] = a^{-1} b^{-1} a b
        cab = mult(mult(mult(inverse(a), inverse(b)), a), b)
        commutators.add(cab)

print(f"\nCommutator elements: {commutators}")
# G' is generated by commutators
# Let's find the subgroup generated by commutators
def generate(gens):
    S = set(['1'])
    changed = True
    while changed:
        changed = False
        for a in list(S):
            for g in gens:
                for prod in [mult(a, g), mult(g, a), mult(a, inverse(g)), mult(inverse(g), a)]:
                    if prod not in S:
                        S.add(prod)
                        changed = True
    return S

G_prime = generate(commutators - {'1'})
print(f"G' = [G,G] = {sorted(G_prime)}")

# Center
center = set()
for a in elements:
    is_central = True
    for b in elements:
        if mult(a, b) != mult(b, a):
            is_central = False
            break
    if is_central:
        center.add(a)
print(f"Z(Q8) = {sorted(center)}")

